cd /workspace/src && python3 - <<'PY'
p='scamptrie_base.cpp'
s=open(p).read()
s=s.replace("""#include "scamptrie_base.h"
#include <cstdio>
#include <cstdlib>

void msg_error(const char* msg) {
    printf("[ERROR] %s\\n", msg);
    exit(1);
}""","""#include "scamptrie_base.h"
#include <cstdio>
#include <cstdlib>
#include <stdexcept>

// Internal invariant violation.  Reported on stderr and raised as an exception
// so that a failing subsystem cannot truncate the JSON response or take the
// whole request down: callers that must stay up catch it around the call.
void msg_error(const char* msg) {
    fprintf(stderr, "[ERROR] %s\\n", msg);
    throw std::runtime_error(msg);
}""")
open(p,'w').write(s)
p='main.cpp'
s=open(p).read()
s=s.replace("""                    // Keep the supplied live core in step with the FIB; its
                    // answer path is not used by the responses.
                    (void)live->insert_prefix(ip, (uint8_t)len, (nexthop_t)hop);""",
"""                    // Keep the supplied live core in step with the FIB.  Its
                    // answer path is not used by the responses, so a rejected
                    // or aborted insert cannot influence them.
                    try {
                        (void)live->insert_prefix(ip, (uint8_t)len, (nexthop_t)hop);
                    } catch (const std::exception&) {
                        // The exact FIB model stays authoritative.
                    }""")
open(p,'w').write(s)
PY
